// 简化版ECharts for 微信小程序
// 注意：这是一个基础实现，建议后续替换为完整版本

const echarts = {
  init: function(canvas, width, height, opts) {
    return new EChartsInstance(canvas, width, height, opts);
  },
  
  setCanvasCreator: function(creator) {
    this.canvasCreator = creator;
  }
};

class EChartsInstance {
  constructor(canvas, width, height, opts) {
    this.canvas = canvas;
    this.width = width;
    this.height = height;
    this.opts = opts || {};
    this._option = null;
  }
  
  setOption(option) {
    this._option = option;
    this.render();
  }
  
  render() {
    if (!this._option || !this.canvas) return;
    
    const ctx = this.canvas.ctx;
    if (!ctx) return;
    
    // 清空画布
    ctx.clearRect(0, 0, this.width, this.height);
    
    // 绘制柱状图
    if (this._option.series && this._option.series[0] && this._option.series[0].type === 'bar') {
      this.renderBarChart(ctx);
    }
  }
  
  renderBarChart(ctx) {
    const series = this._option.series[0];
    const data = series.data || [];
    const xAxis = this._option.xAxis || {};
    const yAxis = this._option.yAxis || {};
    
    if (data.length === 0) return;
    
    // 计算绘图区域
    const padding = 40;
    const chartWidth = this.width - padding * 2;
    const chartHeight = this.height - padding * 2;
    const barWidth = chartWidth / data.length * 0.6;
    const barSpacing = chartWidth / data.length * 0.4;
    
    // 找到最大值用于缩放
    const maxValue = Math.max(...data.map(d => typeof d === 'object' ? d.value : d));
    
    // 绘制柱子
    data.forEach((item, index) => {
      const value = typeof item === 'object' ? item.value : item;
      const barHeight = (value / maxValue) * chartHeight;
      
      const x = padding + index * (barWidth + barSpacing) + barSpacing / 2;
      const y = this.height - padding - barHeight;
      
      // 设置柱子颜色
      const color = series.itemStyle?.color || '#667eea';
      ctx.fillStyle = color;
      
      // 绘制柱子
      ctx.fillRect(x, y, barWidth, barHeight);
      
      // 绘制数值标签
      ctx.fillStyle = '#333';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(value.toString(), x + barWidth / 2, y - 5);
    });
    
    // 绘制X轴标签
    if (xAxis.data) {
      ctx.fillStyle = '#666';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      
      xAxis.data.forEach((label, index) => {
        const x = padding + index * (barWidth + barSpacing) + barSpacing / 2 + barWidth / 2;
        const y = this.height - padding + 15;
        ctx.fillText(label, x, y);
      });
    }
  }
  
  getZr() {
    return {
      handler: {
        dispatch: () => {},
        processGesture: () => {}
      }
    };
  }
  
  resize() {
    this.render();
  }
}

export default echarts;